-- Reference schema; Database.java creates these tables automatically.
CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(24) UNIQUE NOT NULL, password_hash VARCHAR(300) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS challenges(id VARCHAR(30) PRIMARY KEY, game_type VARCHAR(12) NOT NULL, level INT NOT NULL, title VARCHAR(80) NOT NULL, UNIQUE(game_type,level));

CREATE TABLE IF NOT EXISTS attempts(id VARCHAR(40) PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), challenge_id VARCHAR(30) NOT NULL REFERENCES challenges(id), started_at BIGINT NOT NULL, step_index INT DEFAULT 0 NOT NULL, correct_count INT DEFAULT 0 NOT NULL, score INT DEFAULT 0 NOT NULL, elapsed_seconds INT DEFAULT 0 NOT NULL, completed BOOLEAN DEFAULT FALSE NOT NULL);

CREATE TABLE IF NOT EXISTS answers(attempt_id VARCHAR(40) NOT NULL REFERENCES attempts(id), step_index INT NOT NULL, submitted VARCHAR(100) NOT NULL, correct BOOLEAN NOT NULL, PRIMARY KEY(attempt_id,step_index));

CREATE INDEX IF NOT EXISTS attempts_user_idx ON attempts(user_id);
